CREATE TABLE IF NOT EXISTS wait_secrets (session_id VARCHAR(36) NOT NULL, env_name VARCHAR(80) NOT NULL, wait_id VARCHAR(36) NOT NULL, team_id VARCHAR(36) NOT NULL, field_id VARCHAR(64) NOT NULL, owner_id VARCHAR(36) NOT NULL, one_time BOOLEAN NOT NULL, `value` text NOT NULL, created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, CONSTRAINT pk_wait_secrets PRIMARY KEY (session_id, env_name), CONSTRAINT wait_secrets_session FOREIGN KEY (session_id) REFERENCES cloud_sessions(id) ON DELETE CASCADE, CONSTRAINT wait_secrets_wait FOREIGN KEY (wait_id) REFERENCES waits(id) ON DELETE CASCADE);
CREATE INDEX wait_secret_expiry ON wait_secrets (expires_at);
